import type { Metadata } from "next";
import { PERSON, PROFILES, SITE_URL, ZIGEX } from "./site";

export const PERSON_ID = `${SITE_URL}/#person`;
export const WEBSITE_ID = `${SITE_URL}/#website`;
export const ZIGEX_ID = `${ZIGEX.url}#organization`;

export const MAX_TITLE = 65;

/** Generated by app/opengraph-image.tsx */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${PERSON.name} — ${PERSON.headline}`,
};

type PageSeo = {
  /** Page-specific title; the root layout template appends " | Mazwewoh John Brindi". */
  title: string;
  description: string;
  path: `/${string}`;
  keywords?: string[];
  /** Use for pages whose title should NOT get the name suffix (e.g. already contains the name). */
  absoluteTitle?: boolean;
  ogType?: "website" | "profile" | "article";
};

/** Unique title, description, canonical URL and social tags for one page. */
export function pageMetadata({ title, description, path, keywords, absoluteTitle, ogType = "website" }: PageSeo): Metadata {
  // Google truncates titles around 60 characters — drop the name suffix rather than lose the page's own words
  const suffixed = `${title} | ${PERSON.name}`;
  const useAbsolute = absoluteTitle || suffixed.length > MAX_TITLE;
  const fullTitle = useAbsolute ? title : suffixed;
  return {
    title: useAbsolute ? { absolute: title } : title,
    description,
    ...(keywords ? { keywords } : {}),
    alternates: { canonical: path },
    openGraph: {
      type: ogType,
      url: path,
      title: fullTitle,
      description,
      siteName: PERSON.name,
      locale: "en_US",
      // A page-level openGraph object replaces the inherited one, so the image must be repeated here
      images: [DEFAULT_OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [DEFAULT_OG_IMAGE.url],
    },
  };
}

export function personSchema() {
  return {
    "@type": "Person",
    "@id": PERSON_ID,
    name: PERSON.name,
    alternateName: [...PERSON.alternateNames],
    givenName: "John Brindi",
    familyName: "Mazwewoh",
    url: SITE_URL,
    image: {
      "@type": "ImageObject",
      url: `${SITE_URL}${PERSON.image}`,
      width: 1200,
      height: 1800,
    },
    jobTitle: [PERSON.jobTitle, "CEO & Founder of ZIGEX"],
    description: PERSON.description,
    email: `mailto:${PERSON.email}`,
    telephone: PERSON.telephone,
    nationality: { "@type": "Country", name: PERSON.countryName },
    address: {
      "@type": "PostalAddress",
      addressLocality: PERSON.locality,
      addressRegion: PERSON.region,
      addressCountry: PERSON.country,
    },
    alumniOf: {
      "@type": "CollegeOrUniversity",
      name: "National Higher Polytechnic Institute (NAHPI), University of Bamenda",
      address: { "@type": "PostalAddress", addressLocality: "Bamenda", addressCountry: "CM" },
    },
    hasOccupation: [
      {
        "@type": "Occupation",
        name: "CEO & Founder, ZIGEX",
        occupationLocation: { "@type": "City", name: "Bamenda" },
        skills: "Leadership, product strategy, partnerships, system architecture",
      },
      {
        "@type": "Occupation",
        name: "Network & Infrastructure Engineer",
        occupationLocation: { "@type": "Country", name: PERSON.countryName },
        skills: "MPLS, BGP, OSPF, Cisco IOS, LAN/WAN design, network troubleshooting",
      },
      {
        "@type": "Occupation",
        name: "Cybersecurity Instructor",
        occupationLocation: { "@type": "City", name: "Bamenda" },
        skills: "SOC operations, Wazuh SIEM, Suricata, penetration testing",
      },
    ],
    worksFor: { "@id": ZIGEX_ID },
    founder: { "@id": ZIGEX_ID },
    knowsAbout: [...PERSON.knowsAbout],
    knowsLanguage: ["en", "fr"],
    sameAs: [...Object.values(PROFILES), ZIGEX.url],
  };
}

export function organizationSchema() {
  return {
    "@type": "Organization",
    "@id": ZIGEX_ID,
    name: ZIGEX.name,
    alternateName: ZIGEX.alternateName,
    url: ZIGEX.url,
    description: ZIGEX.description,
    founder: { "@id": PERSON_ID },
    areaServed: "Cameroon",
  };
}

export function websiteSchema() {
  return {
    "@type": "WebSite",
    "@id": WEBSITE_ID,
    url: SITE_URL,
    name: PERSON.name,
    alternateName: [PERSON.shortName, `${PERSON.name} Portfolio`],
    description: PERSON.description,
    inLanguage: "en",
    publisher: { "@id": PERSON_ID },
    author: { "@id": PERSON_ID },
  };
}

/** BreadcrumbList for a page, e.g. breadcrumbs([["Projects", "/projects"]]). */
export function breadcrumbSchema(trail: [name: string, path: string][]) {
  return {
    "@type": "BreadcrumbList",
    itemListElement: [["Home", "/"] as [string, string], ...trail].map(([name, path], i) => ({
      "@type": "ListItem",
      position: i + 1,
      name,
      item: `${SITE_URL}${path === "/" ? "" : path}`,
    })),
  };
}

/** Renders one or more schema.org nodes as a single JSON-LD @graph script (XSS-safe). */
export function JsonLd({ data }: { data: object | object[] }) {
  const graph = Array.isArray(data) ? data : [data];
  const json = JSON.stringify({ "@context": "https://schema.org", "@graph": graph }).replace(/</g, "\\u003c");
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: json }} />;
}
